CREATE TABLE issues(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), asset_id TEXT NOT NULL REFERENCES assets(id), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, reported_severity TEXT NOT NULL CHECK(reported_severity IN('low','medium','high','urgent')), status TEXT NOT NULL CHECK(status IN('reported','assigned','investigating','closed')), assignee_id TEXT REFERENCES users(id), version INTEGER NOT NULL, updated_at TEXT NOT NULL, request_key TEXT NOT NULL, UNIQUE(created_by,request_key));
CREATE INDEX issues_plant_time ON issues(plant_id,created_at);
CREATE TABLE issue_events(id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES issues(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, action TEXT NOT NULL, notes TEXT NOT NULL, version INTEGER NOT NULL, UNIQUE(issue_id,version));
CREATE TABLE issue_photos(id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES issues(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, content BLOB NOT NULL, mime_type TEXT NOT NULL);
CREATE TABLE work_user_assignments(work_order_id TEXT NOT NULL REFERENCES work_orders(id), technician_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), assigned_by TEXT NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL, PRIMARY KEY(work_order_id,technician_id));
CREATE INDEX work_user_queue ON work_user_assignments(user_id,work_order_id);
